import json
import re
import zipfile
import xml.etree.ElementTree as ET

# Register namespace to preserve hp: prefix
ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

HP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
NSMAP = {'hp': HP_NS}

# Load JSON data
with open('/root/inventory_data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print("Loaded data keys:")
for k, v in data.items():
    print(f"  {k} -> {v}")

PLACEHOLDER_RE = re.compile(r'\{\{([^}]+)\}\}')

def replace_placeholders(text, data):
    if not text:
        return text, False
    changed = False
    def replacer(m):
        nonlocal changed
        key = m.group(1)
        if key in data:
            changed = True
            return str(data[key])
        return m.group(0)
    new_text = PLACEHOLDER_RE.sub(replacer, text)
    return new_text, changed

def find_paragraph(element):
    """Find the nearest ancestor hp:p element."""
    while element is not None:
        if element.tag == f'{{{HP_NS}}}p':
            return element
        # element may not have a direct parent ref via ElementTree, 
        # but we can build a parent map.
        element = PARENT_MAP.get(element)
    return None

with zipfile.ZipFile('/root/inventory_report_template.hwpx', 'r') as zin:
    with zipfile.ZipFile('/root/inventory_report_ready.hwpx', 'w', zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data_bytes = zin.read(item.filename)
            if item.filename.endswith('.xml'):
                # Parse XML
                tree = ET.ElementTree(ET.fromstring(data_bytes))
                root = tree.getroot()

                # Build parent map
                global PARENT_MAP
                PARENT_MAP = {child: parent for parent in root.iter() for child in parent}

                modified_paragraphs = set()

                # Walk all elements and replace in text and tail
                for elem in root.iter():
                    if elem.text is not None:
                        new_text, changed = replace_placeholders(elem.text, data)
                        if changed:
                            elem.text = new_text
                            para = find_paragraph(elem)
                            if para is not None:
                                modified_paragraphs.add(id(para))
                    if elem.tail is not None:
                        new_tail, changed = replace_placeholders(elem.tail, data)
                        if changed:
                            elem.tail = new_tail
                            para = find_paragraph(elem)
                            if para is not None:
                                modified_paragraphs.add(id(para))

                # Remove linesegarray descendants from modified paragraphs
                if modified_paragraphs:
                    for elem in root.iter():
                        if elem.tag == f'{{{HP_NS}}}p' and id(elem) in modified_paragraphs:
                            # Find and remove all linesegarray descendants
                            to_remove = []
                            for child in elem.iter():
                                if child.tag == f'{{{HP_NS}}}linesegarray':
                                    to_remove.append(child)
                            # Need to remove via parent
                            # Build another parent map for this paragraph subtree if needed
                            # Better: iterate over direct children and recursive
                            # But linesegarray is usually a direct child of p
                            # Let's find all linesegarray under this p and remove them
                            # by finding their immediate parent
                            for target in list(elem.iter(f'{{{HP_NS}}}linesegarray')):
                                # Find parent of target
                                for parent in elem.iter():
                                    for child in list(parent):
                                        if child is target:
                                            parent.remove(child)
                                            break

                # Serialize back to bytes
                xml_bytes = ET.tostring(root, xml_declaration=True, encoding='UTF-8')
                zout.writestr(item, xml_bytes)
            else:
                zout.writestr(item, data_bytes)

print("\nOutput written to /root/inventory_report_ready.hwpx")

# Verification
print("\nVerification:")
with zipfile.ZipFile('/root/inventory_report_ready.hwpx', 'r') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            if '{{' in content:
                print(f'  RESIDUAL PLACEHOLDER in {name}')
            else:
                print(f'  {name}: OK')

print('Verification complete.')
